<?php $s=$settings;$rt=$s['responsavel']??[];$chosen=$s['pagamentos']??[];$hours=[];foreach($s['horarios']??[]as$h)$hours[(int)$h['dia_semana']]=$h;$days=['Domingo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado']; ?>
<section class="settings-page"><div class="page-heading"><div><span class="eyebrow">Administração</span><h1>Configurações</h1><p>Atualize os dados e as preferências do seu estabelecimento.</p></div></div><?php if($success):?><div class="success-alert" role="status"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert" role="alert"><?=e($error)?></div><?php endif;?><form method="post" action="/configuracoes" class="settings-form"><?=csrf_field()?><div class="settings-tabs" role="tablist" aria-label="Categorias das configurações"><button type="button" class="active" role="tab" aria-selected="true" data-settings-tab="profile">Perfil</button><button type="button" role="tab" aria-selected="false" data-settings-tab="operation">Operação</button><button type="button" role="tab" aria-selected="false" data-settings-tab="payments">Pagamentos</button><button type="button" role="tab" aria-selected="false" data-settings-tab="hours">Horários</button></div>
<fieldset><legend>Perfil e contato</legend><div class="settings-grid"><label>Nome completo<input name="name" value="<?=e($s['nome_completo'])?>" maxlength="240" required></label><label>E-mail<input type="email" name="email" value="<?=e($s['email'])?>" maxlength="254" required></label><label>Telefone<input name="phone" value="<?=e($s['numero_telefone_ddd'])?>" inputmode="tel" maxlength="20"></label></div></fieldset>
<fieldset><legend>Estabelecimento</legend><div class="settings-grid"><label>Nome do estabelecimento<input name="trade" value="<?=e($s['nome_fantasia'])?>" maxlength="255" required></label><label>CNPJ<input name="cnpj" value="<?=e($s['cnpj'])?>" maxlength="18" autocapitalize="characters" data-document="cnpj"><small>Aceita o formato numérico e o novo formato alfanumérico.</small></label></div></fieldset>
<fieldset><legend>Operação</legend><div class="settings-options"><label><input type="checkbox" name="vaccines" value="1" <?=!empty($s['aplica_vacinas'])?'checked':''?> data-toggle="settings-rt"><span><b>Aplicar vacinas</b><small>Exige responsável técnico ativo.</small></span></label><label><input type="checkbox" name="invoice" value="1" <?=!empty($s['emitir_nota'])?'checked':''?>><span><b>Emitir nota fiscal</b><small>Mantenha a preparação fiscal habilitada.</small></span></label></div><div class="conditional" data-section="settings-rt" hidden><div class="settings-grid"><label>Responsável técnico<input name="rt_name" value="<?=e($rt['nome']??'')?>" maxlength="240"></label><label>CPF<input name="rt_cpf" value="<?=e($rt['cpf']??'')?>" maxlength="14" inputmode="numeric" data-document="cpf"></label><label>Número do CRMV<input name="rt_number" value="<?=e($rt['numero_conselho']??'')?>" maxlength="40"></label><label>UF<input name="rt_uf" value="<?=e($rt['uf_conselho']??'')?>" maxlength="2" data-uppercase></label><label>Validade<input type="date" name="rt_validity" value="<?=e($rt['validade_conselho']??'')?>"></label><label>E-mail<input type="email" name="rt_email" value="<?=e($rt['email']??'')?>" maxlength="254"></label><label>Telefone<input name="rt_phone" value="<?=e($rt['telefone']??'')?>" maxlength="20"></label></div></div></fieldset>
<fieldset><legend>Formas de pagamento</legend><div class="settings-options"><?php foreach($methods as$m):?><label><input type="checkbox" name="payments[]" value="<?=e($m['codigo'])?>" <?=in_array($m['codigo'],$chosen,true)?'checked':''?>><span><b><?=e($m['nome'])?></b></span></label><?php endforeach;?></div></fieldset>
<fieldset><legend>Horários de funcionamento</legend><div class="settings-hours"><?php foreach($days as$day=>$label):$h=$hours[$day]??['fechado'=>true,'abre_as'=>'','fecha_as'=>''];?><div class="settings-hour"><strong><?=e($label)?></strong><label class="inline-check"><input type="checkbox" name="closed_<?=$day?>" value="1" <?=!empty($h['fechado'])?'checked':''?> data-closed-day="<?=$day?>"> Fechado</label><label>Abre<input type="time" name="open_<?=$day?>" value="<?=e(substr((string)$h['abre_as'],0,5))?>" data-hour-day="<?=$day?>"></label><label>Fecha<input type="time" name="close_<?=$day?>" value="<?=e(substr((string)$h['fecha_as'],0,5))?>" data-hour-day="<?=$day?>"></label></div><?php endforeach;?></div></fieldset>
<div class="settings-save"><button class="primary-button" type="submit">Salvar configurações</button></div></form></section>
